export function parseEventDate(str) {
  const [d, m, y] = str.split(".").map(Number);
  return new Date(2000 + y, m - 1, d);
}

export function getNearestN(filter, n = 8) {
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const pool = filter === "all"
    ? eventLibrary
    : eventLibrary.filter(ev => ev.raum.toLowerCase() === filter.toLowerCase());
  return pool
    .filter(ev => parseEventDate(ev.datum) >= today)
    .sort((a, b) => parseEventDate(a.datum) - parseEventDate(b.datum))
    .slice(0, n);
}

export function findEvent(loc, date) {
  return eventLibrary.find(ev =>
    ev.raum.toLowerCase() === loc?.toLowerCase() && ev.datum === date
  ) || null;
}
  